import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.preprocessing import StandardScaler
from sklearn.model_selection import StratifiedKFold
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Check if any feature shows significant association with outcome
    # using Welch's t-test
    sig_features = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'derived':
            continue  # Skip derived features
        x = feats.x[:, i]
        y = feats.y
        # Split by outcome
        x0 = x[y == 0]
        x1 = x[y == 1]
        if len(x0) > 0 and len(x1) > 0:
            t_stat, p_val = stats.ttest_ind(x0, x1, equal_var=False)
            if p_val < 0.05 and abs(t_stat) > 2.0:
                sig_features.append((fid, abs(t_stat), p_val))

    # Sort by effect size
    sig_features.sort(key=lambda x: x[1], reverse=True)

    # If no significant features, return empty drivers
    if not sig_features:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Check for correlation among top features
    top_fids = [f[0] for f in sig_features[:5]]
    corr_pairs = []
    for i, fid1 in enumerate(top_fids):
        for j, fid2 in enumerate(top_fids[i+1:], i+1):
            col1 = feats.column(fid1)
            col2 = feats.column(fid2)
            corr = np.corrcoef(feats.x[:, col1], feats.x[:, col2])[0, 1]
            if abs(corr) >= 0.6:
                corr_pairs.append((fid1, fid2))

    # Use all significant features except near-duplicates
    selected_features = set()
    for fid, _, _ in sig_features:
        # Check if this feature is correlated with already selected ones
        is_duplicate = False
        for sel_fid in selected_features:
            if (sel_fid, fid) in corr_pairs or (fid, sel_fid) in corr_pairs:
                is_duplicate = True
                break
        if not is_duplicate:
            selected_features.add(fid)

    # For each stratum, check if the effect is consistent
    stratum_effects = defaultdict(list)
    for s in feats.stratum:
        stratum_effects[s] = []

    # Stratified analysis
    skf = StratifiedKFold(n_splits=3, shuffle=True, random_state=42)
    stratum_results = {}

    for s in set(feats.stratum):
        indices = [i for i, st in enumerate(feats.stratum) if st == s]
        if len(indices) < 2:
            continue

        X_s = feats.x[indices]
        y_s = feats.y[indices]

        # Fit logistic regression with all features
        lr = LogisticRegression(penalty='l1', solver='liblinear', C=1.0)
        lr.fit(X_s, y_s)

        # Get coefficients
        coef_dict = dict(zip(feats.ids, lr.coef_[0]))
        stratum_results[s] = coef_dict

    # If we have too few strata or inconsistent effects, return no drivers
    if len(stratum_results) < 2:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Check consistency across strata
    consistent_drivers = []
    for fid in selected_features:
        coefs = []
        for s, coef_dict in stratum_results.items():
            if fid in coef_dict:
                coefs.append(coef_dict[fid])

        if len(coefs) >= 2:
            # Check if coefficients are consistently positive/negative
            if len(set([c > 0 for c in coefs])) == 1:
                consistent_drivers.append(fid)

    # Select best drivers based on effect size
    drivers = []
    for fid, _, _ in sig_features:
        if fid in consistent_drivers:
            drivers.append(fid)
            if len(drivers) >= MAX_DRIVERS:
                break

    # Return final design
    if not drivers:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Select columns and products
    columns = tuple(selected_features)
    products = ()
    loadings = {fid: 1.0 for fid in selected_features}

    return Design(drivers=tuple(drivers), columns=columns, products=products, loadings=loadings)

